<li class="timeline-item" data-state={state} aria-current={state === 'current' ? 'step' : undefined}>{#if dateColumn}<span class="timeline-time timeline-date">{time}</span>{/if}<TimelineMarker {icon} /><div class="timeline-body od-field">{#if !dateColumn && time}{#if datetime}<time class="timeline-time" {datetime}>{time}</time>{:else}<span class="timeline-time">{time}</span>{/if}{/if}<div class="od-cluster timeline-heading"><h4 class="timeline-title">{title}</h4>{#if isSnippet}{@render status()}{:else}<Pill variant={statusVariant} class="timeline-status">{status}</Pill>{/if}</div>{#if meta}<p class="timeline-meta">{meta}</p>{/if}{#if collapsible}<details class="timeline-details" {open}><summary>{summary}</summary>{#if description}<p class="timeline-description">{description}</p>{/if}{@render children?.()}</details>{:else}{#if description}<p class="timeline-description">{description}</p>{/if}{@render children?.()}{/if}</div></li>